R,C=30,8
out=[[8]*C for _ in range(R)]
pts=[(1,6),(3,7),(5,0),(5,7),(9,2),(12,2),(12,4),(17,6),(20,7),(21,5)]
for r,c in pts: out[r][c]=7
for r in range(R):
    cs=[c for rr,c in pts if rr==r]
    if len(cs)>1:
        for c in range(min(cs)+1,max(cs)): out[r][c]=3
for c in range(C):
    rs=[r for r,cc in pts if cc==c]
    if len(rs)>1:
        for r in range(min(rs)+1,max(rs)): out[r][c]=3
print(out)
